from pathlib import Path
import zipfile,xml.etree.ElementTree as E,re,html,json
N={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
def plain(s):
 s=re.sub(r'<(script|style)\\b.*?</\\1>','',s,flags=re.S)
 return html.unescape(re.sub('<["'^>]+>'"',' ',s))
for p in [Path('hanzai_r06_teisei.html'),*Path('hanzai_r06_web').glob('*.html')]:
 s=plain(p.read_text()); s=re.sub(r'[ \\t\\r\\n]+',' ',s)
 Path('evidence',p.stem+'.txt').write_text(s)
books={}
for p in sorted(Path('kyosei').glob('*.xlsx')):
 z=zipfile.ZipFile(p); ss=[]
 if 'xl/sharedStrings.xml' in z.namelist():
  ss=[''.join(x.itertext()) for x in E.fromstring(z.read('xl/sharedStrings.xml'))]
 sheets={}
 for name in z.namelist():
  if re.fullmatch(r'xl/worksheets/sheet\\d+.xml',name):
   rows=[]
   for row in E.fromstring(z.read(name)).findall('.//s:row',N):
    cells={}
    for c in row.findall('s:c',N):
     v=c.find('s:v',N); t=c.get('t'); val=v.text if v is not None else ''
     if t=='s': val=ss[int(val)]
     elif t=='inlineStr': val=''.join(c.find('s:is',N).itertext())
     if val: cells[c.get('r')]=val
    if cells: rows.append(cells)
   sheets[name]=rows
 books[p.name]=sheets
Path('evidence/xlsx.json').write_text(json.dumps(books,ensure_ascii=False,indent=2))
with open('evidence/xlsx_hits.txt','w') as out:
 for f,sheets in books.items():
  for sh,rows in sheets.items():
   for i,row in enumerate(rows):
    if any(re.search('認知症|アルツハイマー',v) for v in row.values()):
     out.write(f'{f} {sh}\\n'+json.dumps(rows[max(0,i-1):i+2],ensure_ascii=False)+'\\n')
with open('evidence/pdf_hits.txt','w') as out:
 for p in sorted(Path('evidence').glob('*r0*.txt')):
  for i,page in enumerate(p.read_text().split('\\f'),1):
   if 'スクリーニング' in page or ('認知症' in page and p.stem=='saihan_r04'):
    out.write(f'\\n=== {p.name} PDF page {i} ===\\n{page}\\n')
